import{_ as t,o as l,c as i,j as a,a as e,a5 as n}from"./chunks/framework.R-FQ1xZ2.js";const m=JSON.parse('{"title":"LangGraph 运行时","description":"State、Node、Edge、Checkpointer、Store 五件套，以及一次 invoke 在图里到底走了什么。","frontmatter":{"title":"LangGraph 运行时","description":"State、Node、Edge、Checkpointer、Store 五件套，以及一次 invoke 在图里到底走了什么。"},"headers":[],"relativePath":"diagrams/langgraph-runtime.md","filePath":"diagrams/langgraph-runtime.md","lastUpdated":null}'),o={name:"diagrams/langgraph-runtime.md"};function h(s,r,c,d,g,p){return l(),i("div",null,[...r[0]||(r[0]=[a("h1",{id:"langgraph-运行时",tabindex:"-1"},[e("LangGraph 运行时 "),a("a",{class:"header-anchor",href:"#langgraph-运行时","aria-label":'Permalink to "LangGraph 运行时"'},"​")],-1),a("p",null,[a("span",{class:"fig-badge"},"架构图"),e(),a("code",null,"architecture")],-1),a("blockquote",null,[a("p",null,[a("strong",null,"一句话"),e("：State、Node、Edge、Checkpointer、Store 五件套，以及一次 invoke 在图里到底走了什么。")])],-1),a("div",{class:"fig-frame"},[a("iframe",{src:"/fig/langgraph-runtime.html",title:"LangGraph 运行时",loading:"lazy",allowfullscreen:""})],-1),n('<p class="fig-actions"><a href="/fig/langgraph-runtime.html" target="_blank" rel="noreferrer">在新窗口打开（可缩放 / 切换明暗主题 / 导出图片）</a></p><h2 id="怎么读这张图" tabindex="-1">怎么读这张图 <a class="header-anchor" href="#怎么读这张图" aria-label="Permalink to &quot;怎么读这张图&quot;">​</a></h2><ol><li>State 是贯穿全图的单一数据结构；每个节点返回的是对 State 的<strong>增量更新</strong>，由 reducer 负责合并。</li><li>普通边是固定的下一步；条件边（conditional edge）读 State 后返回一个出口名，再由 path_map 映射到实际节点。</li><li>节点返回的是部分 State，reducer 决定这个字段是覆盖、追加还是取并集——汇合点出问题几乎都出在这里。</li><li>Checkpointer 在每个 super-step 落一次快照，这就是「重启后能续跑」和「中断后能恢复」的全部原理。</li><li>Store 是跨会话的长期存储，跟 Checkpointer 不是一回事：一个按 thread_id 存会话状态，一个按命名空间存共享记忆。</li></ol><h2 id="面试口径" tabindex="-1">面试口径 <a class="header-anchor" href="#面试口径" aria-label="Permalink to &quot;面试口径&quot;">​</a></h2><ul><li>「LangGraph 和 LangChain 的 AgentExecutor 有什么区别？」——LangGraph 把控制流显式化成图，能表达循环、分支、汇合；AgentExecutor 是一个封死的循环。</li><li>「state reducer 为什么重要？」——节点是并行执行的，没有 reducer 就会出现「后写覆盖先写」；并行分支汇合时尤其明显。</li><li>「interrupt 是怎么实现的？」——在节点之前或之后打断，把当前 State 快照落盘，等外部输入再 resume；本质是 Checkpointer 的一个应用。</li><li>「checkpointer 用内存版会怎样？」——进程一重启就全丢，等于没有。生产必须用持久化后端。</li></ul><h2 id="相关笔记" tabindex="-1">相关笔记 <a class="header-anchor" href="#相关笔记" aria-label="Permalink to &quot;相关笔记&quot;">​</a></h2><ul><li><a href="/learn/kb/l4-agent/">L4 Agent 与工具生态</a></li><li><a href="/learn/diagrams/langchain-ecosystem.html">LangChain 抽象分层</a></li></ul>',7)])])}const f=t(o,[["render",h]]);export{m as __pageData,f as default};
